package com.dy.artisan3d.data.repositoryimport com.dy.artisan3d.data.mapper.toDomainimport com.dy.artisan3d.data.model.artisan.article.ArtisanArticleSingleResponseimport com.dy.artisan3d.domain.model.artisan.ArtisanArticleimport com.dy.artisan3d.domain.repository.ArtisanArticleSingleRepositoryimport com.dy.artisan3d.util.Constants.BASE_URLimport io.ktor.client.HttpClientimport io.ktor.client.call.bodyimport io.ktor.client.request.getclass ArtisanArticleSingleRepositoryImpl(private val httpClient: HttpClient): ArtisanArticleSingleRepository {    override suspend fun getByIdArticle(        id: Int,        lang: String,    ): ArtisanArticle {        return try {            val response: ArtisanArticleSingleResponse = httpClient.get(BASE_URL + "articles/$id").body()            response.data.toDomain(lang)        } catch (e: Exception) {            ArtisanArticle(                0,                "",                "",                "",                "",                ""            )        }    }}